package org.jlinalg.sequence;

import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.BooleanSupplier;

/** Typed UTF-8 input for native chromVAR cores, with explicit peak/cell identities and prepared backgrounds. */
public final class ChromVarIO {
    private ChromVarIO() { }
    public record Limits(long bytes,int lineCharacters,int entries) {
        public Limits {if(bytes<1||bytes>20_000_000_000L||lineCharacters<64||lineCharacters>1_000_000||entries<0||entries>20_000_000)throw new IllegalArgumentException("Invalid chromVAR input capacities");}
        public static Limits defaults(){return new Limits(2_000_000_000L,1_000_000,2_000_000);}
    }
    public record Annotations(List<String> ids,List<String> names,List<int[]> peaks,int repeatedMembers,String format) {
        public Annotations {ids=List.copyOf(ids);names=List.copyOf(names);peaks=peaks.stream().map(int[]::clone).toList();}
        @Override public List<int[]> peaks(){return peaks.stream().map(int[]::clone).toList();}
    }
    public record Groups(ChromVarDeviations.Grouping grouping,int missingAssignments) { }
    private record Entry(int cell,int peak,double value) { }
    public static ChromVarDeviations.Counts counts(Path matrix,Path peakIds,Path cellIds,Limits io,ChromVarDeviations.Limits numeric,BooleanSupplier cancelled)throws IOException {
        List<String> peaks=ids(peakIds,numeric.peaks(),false,io,cancelled),cells=ids(cellIds,numeric.cells(),false,io,cancelled);Entry[] entries;
        try(var in=reader(matrix,io)) {
            String header=line(in,io,cancelled);boolean integer="%%MatrixMarket matrix coordinate integer general".equalsIgnoreCase(header);
            if(!integer&&!"%%MatrixMarket matrix coordinate real general".equalsIgnoreCase(header))throw new IOException("Counts require integer/real coordinate Matrix Market with general symmetry");
            String raw=next(in,io,cancelled);if(raw==null)throw new IOException("Missing count dimensions");String[] shape=fields(raw,3);int p=integer(shape[0],1,numeric.peaks()),c=integer(shape[1],1,numeric.cells()),n=integer(shape[2],0,Math.min(io.entries,numeric.storedValues()));if(p!=peaks.size()||c!=cells.size())throw new IOException("Count dimensions disagree with explicit peak/cell IDs");entries=new Entry[n];int at=0;
            while((raw=next(in,io,cancelled))!=null){if(at==n)throw new IOException("Too many count coordinates");String[] f=fields(raw,3);double value=number(f[2],false);if(value<0||integer&&!f[2].matches("[+-]?[0-9]+"))throw new IOException("Counts require nonnegative numbers; integer fields require integer tokens");entries[at++]=new Entry(integer(f[1],1,c)-1,integer(f[0],1,p)-1,value);}if(at!=n)throw new IOException("Too few count coordinates");
        }
        int[] comparisons={0};Arrays.sort(entries,(a,b)->{if((++comparisons[0]&4095)==0)SignacFragments.check(cancelled);int c=Integer.compare(a.cell,b.cell);return c==0?Integer.compare(a.peak,b.peak):c;});int[] pointers=new int[cells.size()+1],rows=new int[entries.length];double[] values=new double[entries.length];
        for(int i=0;i<entries.length;i++){SignacFragments.check(cancelled);Entry e=entries[i];if(i>0&&e.cell==entries[i-1].cell&&e.peak==entries[i-1].peak)throw new IOException("Duplicate count coordinates: explicitly aggregate with recorded provenance before this input contract");pointers[e.cell+1]++;rows[i]=e.peak;values[i]=e.value;}for(int i=0;i<cells.size();i++)pointers[i+1]+=pointers[i];return new ChromVarDeviations.Counts(peaks,cells,pointers,rows,values,numeric,cancelled);
    }
    /** Matrix inputs are binary presence; index-list inputs preserve every repeated annotation member. */
    public static Annotations annotations(Path source,Path peakIds,Path labels,List<String> peaks,boolean matrix,Limits io,ChromVarDeviations.Limits numeric,BooleanSupplier cancelled)throws IOException {
        if(matrix){var result=SignacMotifIO.read(source,peakIds,labels,new SignacMotifIO.Limits(numeric.peaks(),numeric.annotations(),Math.min(io.entries,20_000_000),io.bytes,io.lineCharacters),cancelled);var input=result.matrix();int[] pointers=input.pointers(),rows=input.rows();double[] values=input.values();List<int[]> indices=new ArrayList<>();for(int motif=0;motif<input.motifs().size();motif++){List<Integer> selected=new ArrayList<>();for(int k=pointers[motif];k<pointers[motif+1];k++){SignacFragments.check(cancelled);if(values[k]!=0&&values[k]!=1)throw new IOException("Motif matrix must be binary presence; use explicit annotation members for intended multiplicity");if(values[k]==1)selected.add(rows[k]+1);}indices.add(selected.stream().mapToInt(Integer::intValue).toArray());}return new Annotations(input.motifs(),input.names(),indices,result.duplicateCoordinates(),"binary-matrix");}
        List<String> ids=new ArrayList<>(),names=new ArrayList<>();Set<String> seen=new HashSet<>();try(var in=reader(labels,io)){if(!"motif_id\tmotif_name".equals(line(in,io,cancelled)))throw new IOException("Require motif_id/motif_name label header");String raw;while((raw=line(in,io,cancelled))!=null){String[] f=raw.split("\t",-1);if(f.length!=2||ids.size()>=numeric.annotations())throw new IOException("Ragged/excessive motif labels");SignacFragments.identity(f[0]);SignacFragments.identity(f[1]);if(!seen.add(f[0]))throw new IOException("Repeated motif ID");ids.add(f[0]);names.add(f[1]);}}
        if(ids.isEmpty())throw new IOException("Require at least one declared motif, including empty annotations");Map<String,Integer> motifIndex=index(ids),peakIndex=index(peaks);List<List<Integer>> members=new ArrayList<>();List<Set<Integer>> distinct=new ArrayList<>();for(int i=0;i<ids.size();i++){members.add(new ArrayList<>());distinct.add(new HashSet<>());}int count=0,repeated=0;
        try(var in=reader(source,io)){if(!"motif_id\tpeak_id".equals(line(in,io,cancelled)))throw new IOException("Require motif_id/peak_id annotation header");String raw;while((raw=line(in,io,cancelled))!=null){String[] f=raw.split("\t",-1);if(f.length!=2||++count>Math.min(io.entries,numeric.annotationIndices()))throw new IOException("Ragged/excessive annotation members");Integer motif=motifIndex.get(f[0]),peak=peakIndex.get(f[1]);if(motif==null||peak==null)throw new IOException("Unknown explicit motif/peak annotation identity");members.get(motif).add(peak+1);if(!distinct.get(motif).add(peak))repeated++;}}
        return new Annotations(ids,names,members.stream().map(v->v.stream().mapToInt(Integer::intValue).toArray()).toList(),repeated,"index-list");
    }
    public static int[][] background(Path path,List<String> peaks,Limits io,ChromVarDeviations.Limits numeric,BooleanSupplier cancelled)throws IOException {
        try(var in=reader(path,io)){String header=line(in,io,cancelled);if(header==null)throw new IOException("Missing background header");String[] columns=header.split("\t",-1);if(!columns[0].equals("peak_id")||(long)peaks.size()*(columns.length-1)>numeric.backgroundValues())throw new IOException("Invalid/excessive background dimensions");for(int j=1;j<columns.length;j++)if(!columns[j].equals("iteration_"+j))throw new IOException("Background iteration headers must be canonical consecutive iteration_1,iteration_2,...");int[][] result=new int[peaks.size()][columns.length-1];String raw;int row=0;while((raw=line(in,io,cancelled))!=null){String[] f=raw.split("\t",-1);if(row>=peaks.size()||f.length!=columns.length||!f[0].equals(peaks.get(row)))throw new IOException("Background peak population/order differs");for(int j=1;j<f.length;j++)result[row][j-1]=integer(f[j],1,peaks.size());row++;}if(row!=peaks.size())throw new IOException("Missing background peak rows");return result;}
    }
    public static Groups groups(Path path,Path levels,List<String> cells,Limits io,BooleanSupplier cancelled)throws IOException {
        List<String> names=ids(levels,2_000_000,true,io,cancelled);Map<String,Integer> index=index(names);int[] assigned=new int[cells.size()];int missing=0;
        try(var in=reader(path,io)){if(!"cell_id\tgroup".equals(line(in,io,cancelled)))throw new IOException("Require cell_id/group header");String raw;int at=0;while((raw=line(in,io,cancelled))!=null){String[] f=raw.split("\t",-1);if(at>=cells.size()||f.length!=2||!f[0].equals(cells.get(at)))throw new IOException("Group cell population/order differs");Integer group=index.get(f[1]);assigned[at++]=group==null?-1:group;if(group==null)missing++;}if(at!=cells.size())throw new IOException("Missing cell group rows");}return new Groups(new ChromVarDeviations.Grouping(names,assigned),missing);
    }
    public static double[] expectation(Path path,List<String> peaks,Limits io,BooleanSupplier cancelled)throws IOException {
        double[] result=new double[peaks.size()];try(var in=reader(path,io)){if(!"peak_id\texpectation".equals(line(in,io,cancelled)))throw new IOException("Require peak_id/expectation header");String raw;int at=0;while((raw=line(in,io,cancelled))!=null){String[] f=raw.split("\t",-1);if(at>=peaks.size()||f.length!=2||!f[0].equals(peaks.get(at)))throw new IOException("Expectation peak population/order differs");result[at++]=number(f[1],true);}if(at!=peaks.size())throw new IOException("Missing expectation peak rows");}return result;
    }
    private static List<String> ids(Path path,int maximum,boolean empty,Limits io,BooleanSupplier cancelled)throws IOException {List<String> ids=new ArrayList<>();Set<String> seen=new HashSet<>();try(var in=reader(path,io)){String raw;while((raw=line(in,io,cancelled))!=null){if(ids.size()==maximum)throw new IOException("Excessive chromVAR identities");SignacFragments.identity(raw);if(!seen.add(raw))throw new IOException("Repeated chromVAR identity");ids.add(raw);}}if(!empty&&ids.isEmpty())throw new IOException("Empty chromVAR identity file");return List.copyOf(ids);}
    private static Map<String,Integer> index(List<String> ids){Map<String,Integer> result=new HashMap<>();for(int i=0;i<ids.size();i++)result.put(ids.get(i),i);return result;}
    private static BufferedReader reader(Path path,Limits limits)throws IOException {if(!Files.isRegularFile(path)||Files.size(path)>limits.bytes)throw new IOException("ChromVAR input unavailable or exceeds byte capacity: "+path);return new BufferedReader(new InputStreamReader(Files.newInputStream(path),StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT)));}
    private static String line(BufferedReader in,Limits limits,BooleanSupplier cancelled)throws IOException {SignacFragments.check(cancelled);StringBuilder raw=new StringBuilder();int c;while((c=in.read())>=0&&c!='\n'){if(raw.length()>=limits.lineCharacters)throw new IOException("ChromVAR line capacity exceeded");raw.append((char)c);}if(c<0&&raw.isEmpty())return null;if(!raw.isEmpty()&&raw.charAt(raw.length()-1)=='\r')raw.setLength(raw.length()-1);return raw.toString();}
    private static String next(BufferedReader in,Limits limits,BooleanSupplier cancelled)throws IOException {String raw;while((raw=line(in,limits,cancelled))!=null)if(!raw.isBlank()&&!raw.startsWith("%"))return raw;return null;}
    private static String[] fields(String raw,int size)throws IOException {String[] f=raw.strip().split("\\s+");if(f.length!=size)throw new IOException("Ragged Matrix Market record");return f;}
    private static int integer(String raw,int min,int max)throws IOException {try{if(!raw.matches("[+]?[0-9]+"))throw new NumberFormatException();int value=Integer.parseInt(raw);if(value<min||value>max)throw new NumberFormatException();return value;}catch(NumberFormatException e){throw new IOException("Invalid bounded chromVAR integer: "+raw,e);}}
    private static double number(String raw,boolean special)throws IOException {if(special)switch(raw){case "NA":return ChromVarDeviations.missingValue();case "NaN":return Double.NaN;case "Inf":return Double.POSITIVE_INFINITY;case "-Inf":return Double.NEGATIVE_INFINITY;default:break;}try{if(!raw.matches("[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?"))throw new NumberFormatException();double value=Double.parseDouble(raw);if(!Double.isFinite(value))throw new NumberFormatException();return value;}catch(NumberFormatException e){throw new IOException("Invalid typed chromVAR numeric token",e);}}
}
